} → path ${pathAmount.toFixed(4)} (${improvement}% more)`);}}}if(accInfo.length)document.getElementById('accumulationInfo').textContent=accInfo.join(' | ');if(document.getElementById('autoOpenTrade').checked)setTimeout(()=>UI.openTradeModal(encodeURIComponent(JSON.stringify(best))),500);}else{document.getElementById('slotResult2').textContent='❌ NO PATH FOUND';}if(State.graphRenderer){State.graphRenderer.buildFromGraph(State.graph,State.opportunities,State.purchasePower,State.highlightedPaths,State.conflictEdges);}const cd=setInterval(()=>{const e=Date.now()-State.lastPullTime;const r=Math.max(0,15000-e);if(r<=0){btn.disabled=false;btn.innerHTML='🎰 PULL LEVER';clearInterval(cd);}else btn.innerHTML=`⏳ ${Math.ceil(r/1000)}s`;},500);},
