path ${pathAmount.toFixed(4)} (${improvement}% more)`);}}}if(accInfo.length)document.getElementById('accumulationInfo').textContent=accInfo.join(' | ');if(document.getElementById('autoOpenTrade').checked)setTimeout(()=>UI.openTradeModal(encodeURIComponent(JSON.stringify(best))),500);}else{document.getElementById('slotResult2').textContent='❌ NO PATH FOUND';}if(State.graphRenderer){State.graphRenderer.buildFromGraph(State.graph,State.opportunities,State.purchasePower,State.highlightedPaths,State.conflictEdges);}const cd=setInterval(()=>{const e=Date.now()-State.lastPullTime;const r=Math.max(0,15000-e);if(r<=0){btn.disabled=false;btn.innerHTML='🎰 PULL LEVER';clearInterval(cd);}else btn.innerHTML=`⏳ ${Math.ceil(r/1000)}s`;},500);addMana('compute',5);},
        async executeAllLines(){if(State.bankroll<=0){log('❌ Cannot execute: bankroll exhausted','error');document.getElementById('batchResult').innerHTML='<span style="color:#ff4444;">❌ Bankroll exhausted.</span>';return;}if(State.liveMode){const walletUrl=document.getElementById('walletProxyUrl').value.trim();if(!walletUrl||!walletUrl.startsWith('http')){log('❌ Live mode requires a valid Wallet Proxy URL','error');return;}}if(!State.highlightedPaths.length){log('No paylines yet, auto‑pulling data…');await Engine.pullGraphLever();if(State.bankroll<=0){log('❌ Bankroll still exhausted after pull','error');return;}if(!State.highlightedPaths.length){log('Still no paylines after auto‑pull.','warning');return;}}const paths=State.highlightedPaths;const totalPaths=paths.length;const perPath=Math.abs(State.bankroll*0.8/totalPaths);let reinvestPercent=Math.min(100,Math.max(0,parseFloat(document.getElementById('reinvestPercent')?.value||50)))/100;log(`🚀 Executing ${totalPaths} paylines with $${perPath.toFixed(2)} each...`);const batchEl=document.getElementById('batchResult');batchEl.innerHTML='<strong>🚀 BATCH EXECUTION</strong><br>';let totalProfit=0;const targets=State.getTargetAssets();const acquired={};const pathDescriptions={};const execUrlBase=document.getElementById('walletProxyUrl').value.trim();const execPath=document.getElementById('execPath').value.trim()||'/execute';for(let i=0;i<paths.length;i++){const path=paths[i];const opp=[...State.opportunities.mega,...State.opportunities.triangular,...State.opportunities.bellman].find(o=>o.path.join('|')===path.join('|'));if(!opp){batchEl.innerHTML+=`<div>Line ${i+1}: ${path.join(' → ')} — ❌ opportunity not found</div>`;continue;}const sz=Math.min(opp.maxTradeSize,perPath);let rt=sz;let valid=true;for(const e of opp.edges){if(!State.validateEdge(e)){valid=false;break;}rt*=e.rate;}if(!valid||!State.validateCycle(opp.edges)){batchEl.innerHTML+=`<div>Line ${i+1}: ${path.join(' → ')} — ⚠️ skipped (suspicious rates)</div>`;log(`⚠️ Line ${i+1} skipped: suspicious rates`,'warning');continue;}const profit=rt-sz;if(profit<0&&Math.abs(profit)>sz*0.5){batchEl.innerHTML+=`<div>Line ${i+1}: ${path.join(' → ')} — ⚠️ skipped (rate stale)</div>`;log(`⚠️ Line ${i+1} skipped: stale rates`,'warning');continue;}if(State.liveMode){try{const resp=await fetch(execUrlBase+execPath,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({paths:opp.path,amount:sz})});if(!resp.ok)throw new Error('Proxy returned '+resp.status);const data=await resp.json();if(!data.success)throw new Error(data.error||'Trade rejected');log(`✅ Line ${i+1} confirmed by proxy`,'success');}catch(err){batchEl.innerHTML+=`<div style="color:#ff4444;">Line ${i+1}: ${path.join(' → ')} — ❌ proxy failed: ${err.message}</div>`;log(`❌ Line ${i+1} proxy error: ${err.message}`,'error');continue;}}State.bankroll+=profit*0.9;State.qFund+=profit*0.05;State.lFund+=profit*0.05;State.matrix+=10+Math.floor(sz/100);totalProfit+=profit;State.addTradeToLedger(opp,sz,profit);const startAsset=path[0];if(targets.includes(startAsset)){const endAmount=sz*(1+opp.profitPercent/100);const price=State.getAssetPrice(startAsset);if(price>0){const acquiredAmount=endAmount/price;State.recordBasketPurchase(startAsset,acquiredAmount,path.join(' → '));if(!acquired[startAsset])acquired[startAsset]=0;acquired[startAsset]+=acquiredAmount;if(!pathDescriptions[startAsset])pathDescriptions[startAsset]=new Set();pathDescriptions[startAsset].add(path.join(' → '));}}batchEl.innerHTML+=`<div style="color:${profit>=0?'var(--green)':'#ff4444'}">Line ${i+1}: ${path.join(' → ')} — $${sz.toFixed(2)} → $${rt.toFixed(2)} (${profit>=0?'+':''}$${profit.toFixed(2)})</div>`;log(`💸 Line ${i+1}: ${path.join(' → ')} profit $${profit.toFixed(2)}`,'success');playWin();}if(reinvestPercent>0&&totalProfit>0&&targets.length&&State.bankroll>0){let reinvestAmount=Math.min(totalProfit*reinvestPercent,State.bankroll);if(reinvestAmount>0){State.bankroll-=reinvestAmount;batchEl.innerHTML+=`<br><strong>💰 Reinvesting $${reinvestAmount.toFixed(2)} into targets...</strong><br>`;for(const t of targets){const price=State.getAssetPrice(t);if(price>0){const amount=reinvestAmount/targets.length/price;State.recordBasketPurchase(t,amount,'Reinvestment');if(!acquired[t])acquired[t]=0;acquired[t]+=amount;if(!pathDescriptions[t])pathDescriptions[t]=new Set();pathDescriptions[t].add('Reinvestment');batchEl.innerHTML+=`<div>📦 ${t}: +${amount.toFixed(6)} @ $${price.toExponential(4)}</div>`;log(`📦 Bought ${amount.toFixed(6)} ${t}`,'success');}}}}State.level=Math.floor(Math.sqrt(State.matrix/10))+1;State.save();UI.updateProfile();batchEl.innerHTML+=`<br><strong>Total profit: $${totalProfit.toFixed(2)}</strong>`;if(Object.keys(acquired).length){batchEl.innerHTML+='<br><strong>🎯 Acquired:</strong><br>';for(const[asset,amount]of Object.entries(acquired)){const paths=pathDescriptions[asset]?[...pathDescriptions[asset]].join(', '):'unknown';batchEl.innerHTML+=`<div>📦 ${asset}: ${amount.toFixed(6)} <small>(via ${paths})</small></div>`;}}confetti(window.innerWidth/2,200,80);addMana('trade',10);syncStateToYjs();},
