        async pullGraphLever(){const now=Date.now();if(now-State.lastPullTime<15000){const r=Math.ceil((15000-(now-State.lastPullTime))/1000);log(`⏳ ${r}s`,'warning');return;}State.lastPullTime=now;const btn=document.getElementById('pullLeverBtn2');btn.disabled=true;btn.innerHTML='🎰 SPINNING…';document.getElementById('slotResult2').textContent='';document.getElementById('accumulationInfo').textContent='';playSpin();await initSystem();const useBellman=document.getElementById('bellmanToggle').checked&&State.level>=5;await runFullScan(true,useBellman);State.computePurchasePower();const multiLineCount=parseInt(document.getElementById('multiLineCount')?.value||7);const all=[...State.opportunities.mega,...State.opportunities.triangular,...State.opportunities.bellman];State.highlightedPaths=[];State.conflictEdges=new Set();if(all.length){all.sort((a,b)=>b.profitPercent-a.profitPercent);const top=all.slice(0,multiLineCount);State.highlightedPaths=top.map(o=>o.path);const edgeCount=new Map();for(const path of State.highlightedPaths){for(let i=0;i<path.length-1;i++){const ek=[path[i],path[i+1]].sort().join('|');edgeCount.set(ek,(edgeCount.get(ek)||0)+1);}}for(const[ek,count]of edgeCount){if(count>1)State.conflictEdges.add(ek);}const best=top[0];document.getElementById('slotResult2').textContent=`🎉 WIN! +${best.profitPercent.toFixed(2)}% — ${best.path.slice(0,4).join(' → ')}`;document.getElementById('slotResult2').style.color=best.profitPercent>5?'#ff00ff':'var(--gold)';confetti(window.innerWidth/2,130,45);const accInfo=[];const targets=State.getTargetAssets();for(const t of targets){const price=State.getAssetPrice(t);if(price>0&&State.bankroll>0){const directAmount=State.bankroll/price;const bestPathForT=all.find(o=>o.path[0]===t&&o.path[o.path.length-1]===t);if(bestPathForT){const pathAmount=State.bankroll*(1+bestPathForT.profitPercent/100)/price;const improvement=((pathAmount-directAmount)/directAmount*100).toFixed(2);accInfo.push(`${t}: direct ${directAmount.toFixed(4)} → 