        async executeAllLines(){if(State.bankroll<=0){log('❌ Cannot execute: bankroll exhausted','error');document.getElementById('batchResult').innerHTML='<span style="color:#ff4444;">❌ Bankroll exhausted.</span>';return;}if(State.liveMode){const walletUrl=document.getElementById('walletProxyUrl').value.trim();if(!walletUrl||!walletUrl.startsWith('http')){log('❌ Live mode requires a valid Wallet Proxy URL','error');return;}}if(!State.highlightedPaths.length){log('No paylines yet, auto‑pulling data…');await Engine.pullGraphLever();if(State.bankroll<=0){log('❌ Bankroll still exhausted after pull','error');return;}if(!State.highlightedPaths.length){log('Still no paylines after auto‑pull.','warning');return;}}const paths=State.highlightedPaths;const totalPaths=paths.length;const perPath=Math.abs(State.bankroll*0.8/totalPaths);let reinvestPercent=Math.min(100,Math.max(0,parseFloat(document.getElementById('reinvestPercent')?.value||50)))/100;log(`🚀 Executing ${totalPaths} paylines with $${perPath.toFixed(2)} each...`);const batchEl=document.getElementById('batchResult');batchEl.innerHTML='<strong>🚀 BATCH EXECUTION</strong><br>';let totalProfit=0;const targets=State.getTargetAssets();const acquired={};const pathDescriptions={};const execUrlBase=document.getElementById('walletProxyUrl').value.trim();const execPath=document.getElementById('execPath').value.trim()||'/execute';for(let i=0;i<paths.length;i++){const path=paths[i];const opp=[...State.opportunities.mega,...State.opportunities.triangular,...State.opportunities.bellman].find(o=>o.path.join('|')===path.join('|'));if(!opp){batchEl.innerHTML+=`<div>Line ${i+1}: ${path.join(' → ')} — ❌ opportunity not found</div>`;continue;}const sz=Math.min(opp.maxTradeSize,perPath);let rt=sz;let valid=true;for(const e of opp.edges){if(!State.validateEdge(e)){valid=false;break;}rt*=e.rate;}if(!valid||!State.validateCycle(opp.edges)){batchEl.innerHTML+=`<div>Line ${i+1}: ${path.join(' → ')} — ⚠️ skipped (suspicious rates)</div>`;log(`⚠️ Line ${i+1} skipped: suspicious rates`,'warning');continue;}const profit=rt-sz;if(profit<0&&Math.abs(profit)>sz*0.5){batchEl.innerHTML+=`<div>Line ${i+1}: ${path.join(' → ')} — ⚠️ skipped (rate stale)</div>`;log(`⚠️ Line ${i+1} skipped: stale rates`,'warning');continue;}if(State.liveMode){try{const resp=await fetch(execUrlBase+execPath,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({paths:opp.path,amount:sz})});if(!resp.ok)throw new Error('Proxy returned '+resp.status);const data=await resp.json();if(!data.success)throw new Error(data.error||'Trade rejected');log(`✅ Line ${i+1} confirmed by proxy`,'success');}catch(err){batchEl.innerHTML+=`<div style="color:#ff4444;">Line ${i+1}: ${path.join(' → ')} — ❌ proxy failed: ${err.message}</div>`;log(`❌ Line ${i+1} proxy error: ${err.message}`,'error');continue;}}State.bankroll+=profit*0.9;State.qFund+=profit*0.05;State.lFund+=profit*0.05;State.matrix+=10+Math.floor(sz/100);totalProfit+=profit;State.addTradeToLedger(opp,sz,profit);const startAsset=path[0];if(targets.includes(startAsset)){const endAmount=sz*(1+opp.profitPercent/100);const price=State.getAssetPrice(startAsset);if(price>0){const acquiredAmount=endAmount/price;State.recordBasketPurchase(startAsset,acquiredAmount,path.join(' → '));if(!acquired[startAsset])acquired[startAsset]=0;acquired[startAsset]+=acquiredAmount;if(!pathDescriptions[startAsset])pathDescriptions[startAsset]=new Set();pathDescriptions[startAsset].add(path.join(' → '));}}batchEl.innerHTML+=`<div style="color:${profit>=0?'var(--green)':'#ff4444'}">Line ${i+1}: ${path.join(' → ')} — $${sz.toFixed(2)} → $${rt.toFixed(2)} (${profit>=0?'+':''}$${profit.toFixed(2)})</div>`;log(`💸 Line ${i+1}: ${path.join(' → ')} profit $${profit.toFixed(2)}`,'success');playWin();}if(reinvestPercent>0&&totalProfit>0&&targets.length&&State.bankroll>0){let reinvestAmount=Math.min(totalProfit*reinvestPercent,State.bankroll);if(reinvestAmount>0){State.bankroll-=reinvestAmount;batchEl.innerH