    function generateP2PQR(peerId) { const loaderHTML = `<!DOCTYPE html><html><head><meta charset="utf-8"><script src="https://unpkg.com/peerjs@1.5.1/dist/peerjs.min.js"></script></head><body style="background:#0a0a1a;color:#0f0;font-family:monospace;text-align:center;padding-top:40vh;">Loading QuanTM FOAM...</body><script>const targetId=window.location.hash.slice(1);const peer=new Peer();peer.on('open',(id)=>{const conn=peer.connect(targetId);conn.on('open',()=>{});conn.on('data',(data)=>{const blob=new Blob([data],{type:'text/html'});const url=URL.createObjectURL(blob);window.location=url;});conn.on('error',()=>{document.body.innerHTML='Connection failed. Try again.';});});peer.on('error',()=>{document.body.innerHTML='Peer error. Try again.';});<\/script></html>`; const fullUrl = 'data:text/html;charset=utf-8,' + encodeURIComponent(loaderHTML) + '#' + peerId; const qrCanvas = document.getElementById('p2pQrCanvas'); QRCode.toCanvas(qrCanvas, fullUrl, { width: 200, margin: 1 }, (err) => { if (err) log('P2P QR error: '+err,'error'); }); }

